import{_ as t,a0 as l,w as o,s as c,ao as d,I as p,x as n,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const N=JSON.parse('{"title":"awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 9 - Learn How to Use Awk Special Patterns begin and end","title":"awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END","tag":"awk","desc":""},"relativePath":"awk/Part 9 - Learn How to Use Awk Special Patterns begin and end.md","filePath":"[post].md"}'),r={name:"awk/Part 9 - Learn How to Use Awk Special Patterns begin and end.md"};function k(h,s,g,m,u,w){const a=l("Link");return o(),c("div",null,[s[13]||(s[13]=d(`<h1 id="awk-系列-如何使用-awk-的特殊模式-begin-和-end" tabindex="-1">awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END <a class="header-anchor" href="#awk-系列-如何使用-awk-的特殊模式-begin-和-end" aria-label="Permalink to “awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END”">​</a></h1><p>在 awk 系列的第八节，我们介绍了一些强大的 awk 命令功能，它们是变量、数字表达式和赋值运算符。</p><p>本节我们将学习更多的 awk 功能，即 awk 的特殊模式：<code>BEGIN</code> 和 <code>END</code>。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Learn-Awk-Patterns-BEGIN-and-END.png" alt=""></p><blockquote><p>学习 awk 的模式 BEGIN 和 END</p></blockquote><p>随着我们逐渐展开，并探索出更多构建复杂 awk 操作的方法，将会证明 awk 的这些特殊功能的是多么强大。</p><p>开始前，先让我们回顾一下 awk 系列的介绍，记得当我们开始这个系列时，我就指出 awk 指令的通用语法是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;script&#39; filenames</span></span></code></pre></div><p>在上述语法中，awk 脚本拥有这样的形式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/pattern/ { actions }</span></span></code></pre></div><p>你通常会发现脚本中的模式（<code>/pattern/</code>）是一个正则表达式，不过你也可以将模式使用特殊模式 <code>BEGIN</code> 和 <code>END</code>。因此，我们也能按照下面的形式编写一条 awk 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>awk &#39;</span></span>
<span class="line"><span>BEGIN { actions } </span></span>
<span class="line"><span>/pattern/ { actions }</span></span>
<span class="line"><span>/pattern/ { actions }</span></span>
<span class="line"><span>……….</span></span>
<span class="line"><span>END { actions } </span></span>
<span class="line"><span>&#39; filenames</span></span></code></pre></div><p>假如你在 awk 脚本中使用了特殊模式：<code>BEGIN</code> 和 <code>END</code>，以下则是它们对应的含义：</p><ul><li><code>BEGIN</code> 模式：是指 awk 将在读取任何输入行之前立即执行 <code>BEGIN</code> 中指定的动作。</li><li><code>END</code> 模式：是指 awk 将在它正式退出前执行 <code>END</code> 中指定的动作。</li></ul><p>含有这些特殊模式的 awk 命令脚本的执行流程如下：</p><ol><li>当在脚本中使用了 <code>BEGIN</code> 模式，则 <code>BEGIN</code> 中所有的动作都会在读取任何输入行之前执行。</li><li>然后，读入一个输入行并解析成不同的段。</li><li>接下来，每一条指定的非特殊模式都会和输入行进行比较匹配，当匹配成功后，就会执行模式对应的动作。对所有你指定的模式重复此执行该步骤。</li><li>再接下来，对于所有输入行重复执行步骤 2 和 步骤 3。</li><li>当读取并处理完所有输入行后，假如你指定了 <code>END</code> 模式，那么将会执行相应的动作。</li></ol><p>当你使用特殊模式时，想要在 awk 操作中获得最好的结果，你应当记住上面的执行顺序。</p><p>为了便于理解，让我们使用第八节的例子进行演示，那个例子是关于 Tecmint 拥有的域名列表，并保存在一个叫做 domains.txt 的文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>news.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>linuxsay.com</span></span>
<span class="line"><span>windows.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>news.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>linuxsay.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>news.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>linuxsay.com</span></span>
<span class="line"><span>windows.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat ~/domains.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/View-Contents-of-File.png" alt=""></p><p><em>查看文件内容</em></p><p>在这个例子中，我们希望统计出 domains.txt 文件中域名 <code>tecmint.com</code> 出现的次数。所以，我们编写了一个简单的 shell 脚本帮助我们完成任务，它使用了变量、数学表达式和赋值运算符的思想，脚本内容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>for file in $@; do</span></span>
<span class="line"><span>if [ -f $file ] ; then</span></span>
<span class="line"><span>### 输出文件名</span></span>
<span class="line"><span>echo &quot;File is: $file&quot;</span></span>
<span class="line"><span>### 输出一个递增的数字记录包含 tecmint.com 的行数</span></span>
<span class="line"><span>awk &#39;/^tecmint.com/ { counter+=1 ; printf &quot;%s\\n&quot;, counter ; }&#39; $file</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>### 若输入不是文件，则输出错误信息</span></span>
<span class="line"><span>echo &quot;$file 不是一个文件，请指定一个文件。&quot; &gt;&amp;2 &amp;&amp; exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span>### 成功执行后使用退出代码 0 终止脚本</span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p>现在让我们像下面这样在上述脚本的 awk 命令中应用这两个特殊模式：<code>BEGIN</code> 和 <code>END</code>：</p><p>我们应当把脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>awk &#39;/^tecmint.com/ { counter+=1 ; printf &quot;%s\\n&quot;, counter ; }&#39; $file</span></span></code></pre></div><p>改成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>awk &#39; BEGIN {  print &quot;文件中出现 tecmint.com 的次数是：&quot; ; }</span></span>
<span class="line"><span>/^tecmint.com/ {  counter+=1  ;  }</span></span>
<span class="line"><span>END {  printf &quot;%s\\n&quot;,  counter  ; } </span></span>
<span class="line"><span>&#39;  $file</span></span></code></pre></div><p>在修改了 awk 命令之后，现在完整的 shell 脚本就像下面这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>for file in $@; do</span></span>
<span class="line"><span>if [ -f $file ] ; then</span></span>
<span class="line"><span>### 输出文件名</span></span>
<span class="line"><span>echo &quot;File is: $file&quot;</span></span>
<span class="line"><span>### 输出文件中 tecmint.com 出现的总次数</span></span>
<span class="line"><span>awk &#39; BEGIN {  print &quot;文件中出现 tecmint.com 的次数是：&quot; ; }</span></span>
<span class="line"><span>/^tecmint.com/ {  counter+=1  ;  }</span></span>
<span class="line"><span>END {  printf &quot;%s\\n&quot;,  counter  ; } </span></span>
<span class="line"><span>&#39;  $file</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>### 若输入不是文件，则输出错误信息</span></span>
<span class="line"><span>echo &quot;$file 不是一个文件，请指定一个文件。&quot; &gt;&amp;2 &amp;&amp; exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span>### 成功执行后使用退出代码 0 终止脚本</span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Awk-BEGIN-and-END-Patterns.png" alt=""></p><p><em>awk 模式 BEGIN 和 END</em></p><p>当我们运行上面的脚本时，它会首先输出 domains.txt 文件的位置，然后执行 awk 命令脚本，该命令脚本中的特殊模式 <code>BEGIN</code> 将会在从文件读取任何行之前帮助我们输出这样的消息“<code>文件中出现 tecmint.com 的次数是：</code>”。</p><p>接下来，我们的模式 <code>/^tecmint.com/</code> 会在每个输入行中进行比较，对应的动作 <code>{ counter+=1 ; }</code> 会在每个匹配成功的行上执行，它会统计出 <code>tecmint.com</code> 在文件中出现的次数。</p><p>最终，<code>END</code> 模式将会输出域名 <code>tecmint.com</code> 在文件中出现的总次数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./script.sh ~/domains.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Script-to-Count-Number-of-Times-String-Appears.png" alt=""></p><p><em>用于统计字符串出现次数的脚本</em></p><p>最后总结一下，我们在本节中演示了更多的 awk 功能，并学习了特殊模式 <code>BEGIN</code> 和 <code>END</code> 的概念。</p><p>正如我之前所言，这些 awk 功能将会帮助我们构建出更复杂的文本过滤操作。第十节将会给出更多的 awk 功能，我们将会学习 awk 内置变量的思想，所以，请继续保持关注。</p><hr>`,42)),p("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"http://www.tecmint.com/learn-use-awk-special-patterns-begin-and-end/"},{default:i(()=>[...s[0]||(s[0]=[n("http://www.tecmint.com/learn-use-awk-special-patterns-begin-and-end/",-1)])]),_:1})]),p("p",null,[s[5]||(s[5]=n("作者：",-1)),e(a,{href:"http://www.tecmint.com/author/aaronkili/"},{default:i(()=>[...s[2]||(s[2]=[n("Aaron Kili",-1)])]),_:1}),s[6]||(s[6]=n(" 译者：",-1)),e(a,{href:"https://github.com/chrisleegit"},{default:i(()=>[...s[3]||(s[3]=[n("ChrisLeeGit",-1)])]),_:1}),s[7]||(s[7]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[10]||(s[10]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[8]||(s[8]=[n("LCTT",-1)])]),_:1}),s[11]||(s[11]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[9]||(s[9]=[n("Linux中国",-1)])]),_:1}),s[12]||(s[12]=n(" 荣誉推出",-1))])])}const E=t(r,[["render",k]]);export{N as __pageData,E as default};
